import functools

def count_calls(func):
    @functools.wraps(func)               # keep func's name and docstring
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)     # pass everything through, return the result
    wrapper.calls = 0
    return wrapper

@count_calls                             # same as: greet = count_calls(greet)
def greet(name):
    """Say hello."""
    return f"Hello, {name}"

greet("Ada")
greet("Linus")
print(greet.calls, greet.__name__, greet.__doc__)   # 2 greet Say hello.

def retry(times):                        # a decorator factory: returns a decorator
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except ConnectionError as err:
                    print(f"attempt {attempt} failed: {err}")
            raise ConnectionError(f"gave up after {times} attempts")
        return wrapper
    return decorator

replies = iter([ConnectionError("timeout"), ConnectionError("reset"), "200 OK"])

@retry(times=3)
def fetch():
    reply = next(replies)
    if isinstance(reply, Exception):
        raise reply
    return reply

print(fetch())
# attempt 1 failed: timeout
# attempt 2 failed: reset
# 200 OK

