from functools import cache, cached_property, lru_cache, partial, reduce, singledispatch
import operator

@cache                                   # unbounded memo, like lru_cache(maxsize=None)
def ways(n):
    """Ways to climb n stairs taking 1 or 2 steps at a time."""
    return 1 if n <= 1 else ways(n - 1) + ways(n - 2)

print(ways(80))                          # 37889062373143906, instantly
print(ways.cache_info().hits)            # 78

@lru_cache(maxsize=2)                    # bounded: keeps the 2 most recent
def lookup(code):
    print("  computing", code)
    return code.upper()

for c in ["us", "fr", "us", "de", "fr"]:
    lookup(c)                            # fr is computed twice: it was evicted

from_binary = partial(int, base=2)       # pre-fill an argument
print(from_binary("1011"))               # 11

print(reduce(operator.mul, [1, 2, 3, 4], 1))   # 24

class Report:
    def __init__(self, rows):
        self.rows = rows

    @cached_property                     # computed on first access, then stored
    def total(self):
        print("  summing...")
        return sum(self.rows)

r = Report([5, 10])
print(r.total, r.total)                  # "summing..." once, then 15 15

@singledispatch
def describe(value):
    return f"something: {value!r}"

@describe.register
def _(value: list):
    return f"a list of {len(value)}"

print(describe(3), "|", describe([1, 2]))     # something: 3 | a list of 2

