import json

class AppError(Exception):
    """Base class: callers can catch everything this package raises."""

class ConfigError(AppError):
    pass

def load_port(text):
    try:
        return json.loads(text)["port"]
    except json.JSONDecodeError as err:
        raise ConfigError("config is not valid JSON") from err
    except KeyError:
        raise ConfigError("config is missing 'port'") from None

for text in ['{"port": 8080}', '{"port": ', '{"host": "x"}']:
    try:
        print("port", load_port(text))
    except AppError as err:
        cause = type(err.__cause__).__name__ if err.__cause__ else None
        print(f"{type(err).__name__}: {err} (cause: {cause})")

# Several independent failures at once (3.11+)
def validate(user):
    problems = []
    if "@" not in user["email"]:
        problems.append(ValueError("email has no @"))
    if user["age"] < 0:
        problems.append(ValueError("age is negative"))
    if problems:
        raise ExceptionGroup("invalid user", problems)

try:
    validate({"email": "nobody", "age": -1})
except* ValueError as group:
    for e in group.exceptions:
        print("-", e)

